update public.questions set stem = 'أيّ العبارات الآتية تصف السكريات الأحادية وصفًا صحيحًا؟', options = '["تتكون من اتحاد جزيئين من السكريات البسيطة، وأشيعها يحتوي على اثنتي عشرة ذرة كربون","أعقد أنواع الكربوهيدرات، وتتكون من مئات أو آلاف من وحدات البناء الأساسية","أبسط أنواع الكربوهيدرات وتُسمى السكريات البسيطة، وأشيعها يحتوي على خمس أو ست ذرات كربون","أبسط أنواع الكربوهيدرات، وأشيعها يحتوي على ثلاث أو أربع ذرات كربون فقط"]'::jsonb, question_kind = 'وصف وتصنيف', source_ref = 'الكتاب ص 216 — السكريات الأحادية', updated_at = now() where id = (select id from public.questions where objective_id = (select id from public.objectives where code = 'K22-C6-L2-O01') and type = 'mcq' and number = 4);
update public.question_answers set explanation = 'السكريات الأحادية أبسط أنواع الكربوهيدرات، وكثيرًا ما تُسمى السكريات البسيطة، وتحتوي أكثرها شيوعًا على خمس أو ست ذرات كربون، مثل الرايبوز (خماسي الكربون) والجلوكوز والفركتوز (سداسية الكربون).', distractor_notes = '["هذا وصف السكريات الثنائية؛ إذ يتكون السكر الثنائي من سكرين أحاديين، ومثاله السكروز C₁₂H₂₂O₁₁.","هذا وصف السكريات عديدة التسكر، وهي بوليمرات من السكريات البسيطة، أما السكر الأحادي فوحدة بناء واحدة.","","صحيح أنها أبسط الكربوهيدرات، لكن أشيعها يحتوي على خمس أو ست ذرات كربون، مثل الجلوكوز C₆H₁₂O₆."]'::jsonb where question_id = (select id from public.questions where objective_id = (select id from public.objectives where code = 'K22-C6-L2-O01') and type = 'mcq' and number = 4);
update public.questions set source_ref = 'الكتاب ص 216–217 — أنواع الكربوهيدرات وماذا قرأت؟', updated_at = now() where id = (select id from public.questions where objective_id = (select id from public.objectives where code = 'K22-C6-L2-O01') and type = 'essay' and number = 2);
update public.questions set images = '[{"src":"qimg/chem22/c6-l2-glu-ring-open.svg","alt":"صورتان لسكر أحادي واحد بينهما سهم اتزان مزدوج (⇌). (س) صورة حلقية: حلقة سداسية مسطحة مرسومة منظورًا (أضلاعها الأمامية سميكة) من خمس ذرات كربون وذرة أكسجين في الركن الخلفي الأيمن. ذرة الكربون الخلفية اليسرى: CH₂OH إلى أعلى وH إلى أسفل. ذرة الكربون اليمنى المجاورة لأكسجين الحلقة: H إلى أعلى وOH إلى أسفل. الأمامية اليمنى: H إلى أعلى وOH إلى أسفل. الأمامية اليسرى: OH إلى أعلى وH إلى أسفل. ذرة الكربون اليسرى: H إلى أعلى وHO إلى أسفل. (ص) صورة مفتوحة السلسلة: سلسلة رأسية من ست ذرات كربون. في الأعلى ذرة H مرتبطة بذرة الكربون الأولى، وهذه مرتبطة برابطة ثنائية مع ذرة O يمينًا (H–C=O)؛ ثم ذرة كربون عليها H يسارًا وOH يمينًا؛ ثم ذرة كربون عليها HO يسارًا وH يمينًا؛ ثم ثلاث ذرات كربون على كلٍّ منها H يسارًا وOH يمينًا؛ وفي الأسفل ذرة H مرتبطة بآخر ذرة كربون."}]'::jsonb, source_ref = 'الكتاب ص 216–217 — الشكل 6-9: الاتزان بين الشكل الحلقي وشكل السلسلة المفتوحة', updated_at = now() where id = (select id from public.questions where objective_id = (select id from public.objectives where code = 'K22-C6-L2-O03') and type = 'mcq' and number = 4);
update public.questions set stem = 'سكر أحادي صلب أبيض، يحتوي جزيئه على عدة مجموعات هيدروكسيل (–OH) بالإضافة إلى مجموعة كربونيل (C=O). ما الخاصيتان المتوقعتان له؟', options = '["يذوب في الماء، ودرجة انصهاره عالية؛ لتعدد المجموعات القطبية في جزيئه","لا يذوب في الماء، ودرجة انصهاره منخفضة؛ لأنه مركب عضوي","يذوب في الماء، ودرجة انصهاره منخفضة؛ لأن جزيئه صغير","لا يذوب في الماء، ودرجة انصهاره عالية؛ لطول سلسلته الكربونية"]'::jsonb, question_kind = 'تنبؤ بالخواص', source_ref = 'الكتاب ص 216 — ذوبان السكريات الأحادية ودرجات انصهارها', updated_at = now() where id = (select id from public.questions where objective_id = (select id from public.objectives where code = 'K22-C6-L2-O03') and type = 'mcq' and number = 6);
update public.question_answers set explanation = 'تعدد المجموعات القطبية (عدة مجموعات –OH ومجموعة C=O) في جزيء السكر الأحادي يجعله قابلًا للذوبان في الماء، ويعطيه درجة انصهار عالية.', distractor_notes = '["","كونه مركبًا عضويًّا لا يعني أنه لا يذوب؛ فتعدد مجموعاته القطبية يجعله يذوب في الماء ويرفع درجة انصهاره.","الذوبان صحيح، لكن تعدد المجموعات القطبية يعطي السكريات الأحادية درجات انصهار عالية لا منخفضة.","درجة الانصهار العالية صحيحة، لكن تعدد المجموعات القطبية في جزيئه يجعله يذوب في الماء، وليس طول السلسلة هو ما يحدد ذلك."]'::jsonb where question_id = (select id from public.questions where objective_id = (select id from public.objectives where code = 'K22-C6-L2-O03') and type = 'mcq' and number = 6);
update public.questions set source_ref = 'الكتاب ص 216–217 — السكريات الأحادية في المحاليل المائية (الشكل 6-9)', updated_at = now() where id = (select id from public.questions where objective_id = (select id from public.objectives where code = 'K22-C6-L2-O03') and type = 'essay' and number = 3);
update public.questions set source_ref = 'الكتاب ص 216 — تعريف الكربوهيدرات', updated_at = now() where id = (select id from public.questions where objective_id = (select id from public.objectives where code = 'K22-C6-L2-O04') and type = 'mcq' and number = 1);
update public.questions set images = '[{"src":"qimg/chem22/c6-l2-fructose-ring.svg","alt":"تركيب حلقي لسكر أحادي: حلقة خماسية مسطحة مرسومة منظورًا (أضلاعها الأمامية سميكة) من أربع ذرات كربون وذرة أكسجين في أعلاها. ذرة الكربون اليسرى المجاورة للأكسجين: CH₂OH إلى أعلى وHO إلى أسفل. الأمامية اليسرى: H إلى أعلى وOH إلى أسفل. الأمامية اليمنى: HO إلى أعلى وH إلى أسفل. ذرة الكربون اليمنى المجاورة للأكسجين: H إلى أعلى وCH₂OH إلى أسفل."}]'::jsonb, source_ref = 'الكتاب ص 216 — الشكل 6-9: الفركتوز الحلقي', updated_at = now() where id = (select id from public.questions where objective_id = (select id from public.objectives where code = 'K22-C6-L2-O04') and type = 'mcq' and number = 2);
update public.questions set images = '[{"src":"qimg/chem22/c6-l2-glucose-open.svg","alt":"تركيب مفتوح السلسلة لسكر أحادي: سلسلة رأسية من ست ذرات كربون. في الأعلى ذرة H مرتبطة بذرة الكربون الأولى، وهذه مرتبطة برابطة ثنائية مع ذرة O يمينًا (H–C=O)؛ ثم ذرة كربون عليها H يسارًا وOH يمينًا؛ ثم ذرة كربون عليها HO يسارًا وH يمينًا؛ ثم ثلاث ذرات كربون على كلٍّ منها H يسارًا وOH يمينًا؛ وفي الأسفل ذرة H مرتبطة بآخر ذرة كربون."}]'::jsonb, source_ref = 'الكتاب ص 216 — الشكل 6-9: الجلوكوز مفتوح السلسلة', updated_at = now() where id = (select id from public.questions where objective_id = (select id from public.objectives where code = 'K22-C6-L2-O04') and type = 'mcq' and number = 3);
update public.question_answers set explanation = 'في التركيب خمس مجموعات OH على ذرات الكربون من الثانية إلى السادسة، ومجموعة C=O واحدة على ذرة الكربون الأولى في أعلى السلسلة؛ أي 5 مجموعات هيدروكسيل ومجموعة كربونيل واحدة.', distractor_notes = '["إغفال مجموعة OH على ذرة الكربون الأخيرة في أسفل السلسلة.","عدّ ذرة أكسجين الكربونيل مجموعة هيدروكسيل، مع أنها مرتبطة برابطة ثنائية C=O ولا تحمل H.","يوجد في التركيب رابطة ثنائية C=O واحدة فقط في أعلى السلسلة.",""]'::jsonb where question_id = (select id from public.questions where objective_id = (select id from public.objectives where code = 'K22-C6-L2-O04') and type = 'mcq' and number = 3);
update public.questions set source_ref = 'الكتاب ص 216، 244 — تعريف الكربوهيدرات', updated_at = now() where id = (select id from public.questions where objective_id = (select id from public.objectives where code = 'K22-C6-L2-O04') and type = 'mcq' and number = 4);
update public.questions set source_ref = 'الكتاب ص 216، 236 — الصيغة العامة Cₙ(H₂O)ₙ', updated_at = now() where id = (select id from public.questions where objective_id = (select id from public.objectives where code = 'K22-C6-L2-O04') and type = 'mcq' and number = 5);
update public.questions set images = '[{"src":"qimg/chem22/c6-l2-glucose-ring.svg","alt":"تركيب حلقي لسكر أحادي: حلقة سداسية مسطحة مرسومة منظورًا (أضلاعها الأمامية سميكة) من خمس ذرات كربون وذرة أكسجين في الركن الخلفي الأيمن. ذرة الكربون الخلفية اليسرى: CH₂OH إلى أعلى وH إلى أسفل. ذرة الكربون اليمنى المجاورة لأكسجين الحلقة: H إلى أعلى وOH إلى أسفل. الأمامية اليمنى: H إلى أعلى وOH إلى أسفل. الأمامية اليسرى: OH إلى أعلى وH إلى أسفل. ذرة الكربون اليسرى: H إلى أعلى وHO إلى أسفل."}]'::jsonb, source_ref = 'الكتاب ص 216–217 — الشكل 6-9 وتحول الكربونيل إلى هيدروكسيل في التركيب الحلقي', updated_at = now() where id = (select id from public.questions where objective_id = (select id from public.objectives where code = 'K22-C6-L2-O04') and type = 'mcq' and number = 6);
update public.questions set source_ref = 'الكتاب ص 216 — أصل تسمية الكربوهيدرات', updated_at = now() where id = (select id from public.questions where objective_id = (select id from public.objectives where code = 'K22-C6-L2-O04') and type = 'mcq' and number = 7);
update public.question_answers set explanation = 'أدت ملاحظات قديمة إلى أن الصيغة العامة لهذه المركبات Cₙ(H₂O)ₙ؛ ففي صيغها نسبة ذرات الهيدروجين إلى ذرات الأكسجين 2 : 1 كما في الماء (C₆H₁₂O₆ تبدو C₆(H₂O)₆)، فبدت كأنها «هيدرات الكربون» وسُمّيت كربوهيدرات. ومع أنه لا توجد جزيئات ماء كاملة مرتبطة بها، إذ إن ذرات الهيدروجين والأكسجين موزعة في مجموعات هيدروكسيل وكربونيل، فقد بقي الاسم دون تغيير.' where question_id = (select id from public.questions where objective_id = (select id from public.objectives where code = 'K22-C6-L2-O04') and type = 'mcq' and number = 7);
update public.questions set source_ref = 'الكتاب ص 216، 244 — تعريف الكربوهيدرات', updated_at = now() where id = (select id from public.questions where objective_id = (select id from public.objectives where code = 'K22-C6-L2-O04') and type = 'essay' and number = 1);
update public.questions set images = '[{"src":"qimg/chem22/c6-l2-glucose-open.svg","alt":"تركيب مفتوح السلسلة لسكر أحادي: سلسلة رأسية من ست ذرات كربون. في الأعلى ذرة H مرتبطة بذرة الكربون الأولى، وهذه مرتبطة برابطة ثنائية مع ذرة O يمينًا (H–C=O)؛ ثم ذرة كربون عليها H يسارًا وOH يمينًا؛ ثم ذرة كربون عليها HO يسارًا وH يمينًا؛ ثم ثلاث ذرات كربون على كلٍّ منها H يسارًا وOH يمينًا؛ وفي الأسفل ذرة H مرتبطة بآخر ذرة كربون."}]'::jsonb, source_ref = 'الكتاب ص 216 — المجموعات الوظيفية والصيغة Cₙ(H₂O)ₙ (الشكل 6-9)', updated_at = now() where id = (select id from public.questions where objective_id = (select id from public.objectives where code = 'K22-C6-L2-O04') and type = 'essay' and number = 2);
update public.question_answers set model_answer = '(أ) يحتوي على خمس مجموعات هيدروكسيل (–OH): على ذرات الكربون من الثانية إلى السادسة، ومجموعة كربونيل واحدة (C=O) في أعلى السلسلة. (ب) عدد الذرات: C = 6، H = 12، O = 6، فالصيغة C₆H₁₂O₆ = C₆(H₂O)₆ حيث n = 6. (ج) لأنه يحتوي على عدة مجموعات هيدروكسيل بالإضافة إلى مجموعة الكربونيل، وهذا تعريف الكربوهيدرات.', common_errors = '["إغفال OH على ذرة الكربون الأخيرة في أسفل السلسلة","عدّ أكسجين الكربونيل ضمن مجموعات OH","كتابة الصيغة C₆H₁₀O₆"]'::jsonb where question_id = (select id from public.questions where objective_id = (select id from public.objectives where code = 'K22-C6-L2-O04') and type = 'essay' and number = 2);
update public.questions set source_ref = 'الكتاب ص 216، 236، 244 — تعريف الكربوهيدرات والصيغة العامة', updated_at = now() where id = (select id from public.questions where objective_id = (select id from public.objectives where code = 'K22-C6-L2-O04') and type = 'essay' and number = 3);
update public.question_answers set model_answer = '(1) كربوهيدرات: فيه مجموعتا OH ومجموعة كربونيل (–CHO). (2) ليس كربوهيدرات: فيه ثلاث مجموعات OH ولا توجد مجموعة كربونيل. (3) كربوهيدرات: فيه مجموعتا OH ومجموعة كربونيل (C=O بين ذرتي كربون). (4) ليس كربوهيدرات: فيه مجموعة كربوكسيل –COOH وليست فيه عدة مجموعات هيدروكسيل. ومع أن صيغة (4) الجزيئية C₂H₄O₂ يمكن كتابتها C₂(H₂O)₂ فإنه ليس كربوهيدرات؛ لذا فالحكم يكون بالمجموعات الوظيفية؛ ولا توجد في الكربوهيدرات أصلًا جزيئات ماء كاملة رغم الاسم (عدة OH مع C=O) لا بالصيغة الجزيئية وحدها.' where question_id = (select id from public.questions where objective_id = (select id from public.objectives where code = 'K22-C6-L2-O04') and type = 'essay' and number = 3);
update public.questions set images = '[{"src":"qimg/chem22/c6-l2-three-rings.svg","alt":"ثلاثة تراكيب حلقية لسكريات أحادية. (أ): حلقة سداسية مسطحة مرسومة منظورًا (أضلاعها الأمامية سميكة) من خمس ذرات كربون وذرة أكسجين في الركن الخلفي الأيمن. ذرة الكربون الخلفية اليسرى: CH₂OH إلى أعلى وH إلى أسفل. ذرة الكربون اليمنى المجاورة لأكسجين الحلقة: H إلى أعلى وOH إلى أسفل. الأمامية اليمنى: H إلى أعلى وOH إلى أسفل. الأمامية اليسرى: OH إلى أعلى وH إلى أسفل. ذرة الكربون اليسرى: H إلى أعلى وHO إلى أسفل. (ب): حلقة خماسية مسطحة مرسومة منظورًا (أضلاعها الأمامية سميكة) من أربع ذرات كربون وذرة أكسجين في أعلاها. ذرة الكربون اليسرى المجاورة للأكسجين: CH₂OH إلى أعلى وHO إلى أسفل. الأمامية اليسرى: H إلى أعلى وOH إلى أسفل. الأمامية اليمنى: HO إلى أعلى وH إلى أسفل. ذرة الكربون اليمنى المجاورة للأكسجين: H إلى أعلى وCH₂OH إلى أسفل. (ج): حلقة سداسية مماثلة تمامًا، فيها المجموعات نفسها في المواقع نفسها، إلا أن ذرة الكربون اليسرى تحمل HO إلى أعلى وH إلى أسفل (عكس (أ))."}]'::jsonb, source_ref = 'الكتاب ص 216 — الشكل 6-9: التراكيب الحلقية', updated_at = now() where id = (select id from public.questions where objective_id = (select id from public.objectives where code = 'K22-C6-L2-O05') and type = 'mcq' and number = 2);
update public.questions set images = '[{"src":"qimg/chem22/c6-l2-glu-gal-rings.svg","alt":"تركيبان حلقيان لسكرين أحاديين. (س): حلقة سداسية مسطحة مرسومة منظورًا (أضلاعها الأمامية سميكة) من خمس ذرات كربون وذرة أكسجين في الركن الخلفي الأيمن. ذرة الكربون الخلفية اليسرى: CH₂OH إلى أعلى وH إلى أسفل. ذرة الكربون اليمنى المجاورة لأكسجين الحلقة: H إلى أعلى وOH إلى أسفل. الأمامية اليمنى: H إلى أعلى وOH إلى أسفل. الأمامية اليسرى: OH إلى أعلى وH إلى أسفل. ذرة الكربون اليسرى: H إلى أعلى وHO إلى أسفل. (ص): حلقة سداسية مماثلة تمامًا، فيها المجموعات نفسها في المواقع نفسها، إلا أن ذرة الكربون اليسرى تحمل HO إلى أعلى وH إلى أسفل (عكس (س))."}]'::jsonb, source_ref = 'الكتاب ص 216–217 — الشكل 6-9 والجلاكتوز متشكل هندسي للجلوكوز', updated_at = now() where id = (select id from public.questions where objective_id = (select id from public.objectives where code = 'K22-C6-L2-O05') and type = 'mcq' and number = 3);
update public.question_answers set explanation = 'الحلقتان متماثلتان في عدد الذرات وترتيبها، والفرق الوحيد اتجاه ذرة H ومجموعة OH على ذرة الكربون اليسرى (OH إلى أسفل في (س) وإلى أعلى في (ص))؛ فهما متشكلان هندسيان (الجلوكوز والجلاكتوز).' where question_id = (select id from public.questions where objective_id = (select id from public.objectives where code = 'K22-C6-L2-O05') and type = 'mcq' and number = 3);
update public.questions set images = '[{"src":"qimg/chem22/c6-l2-open-three.svg","alt":"ثلاثة تراكيب مفتوحة السلسلة لسكريات أحادية. (أ): سلسلة رأسية من ست ذرات كربون. في الأعلى ذرة H مرتبطة بذرة الكربون الأولى، وهذه مرتبطة برابطة ثنائية مع ذرة O يمينًا (H–C=O)؛ ثم ذرة كربون عليها H يسارًا وOH يمينًا؛ ثم ذرة كربون عليها HO يسارًا وH يمينًا؛ ثم ثلاث ذرات كربون على كلٍّ منها H يسارًا وOH يمينًا؛ وفي الأسفل ذرة H مرتبطة بآخر ذرة كربون. (ب): سلسلة رأسية مماثلة من ست ذرات كربون أعلاها H–C=O (ذرة H فوق ذرة الكربون الأولى)، ثم ذرة كربون عليها H يسارًا وOH يمينًا، ثم ذرتا كربون على كلٍّ منهما HO يسارًا وH يمينًا، ثم ذرتا كربون على كلٍّ منهما H يسارًا وOH يمينًا، وفي الأسفل ذرة H. (ج): سلسلة رأسية من ست ذرات كربون: في الأعلى ذرة H مرتبطة بذرة كربون عليها H يسارًا وOH يمينًا، تليها ذرة كربون مرتبطة برابطة ثنائية مع ذرة O يمينًا (C=O) دون ذرة H، ثم ذرة كربون عليها HO يسارًا وH يمينًا، ثم ثلاث ذرات كربون على كلٍّ منها H يسارًا وOH يمينًا، وفي الأسفل ذرة H."}]'::jsonb, source_ref = 'الكتاب ص 216–217 — موقع الكربونيل: الجلوكوز ألدهيدي والفركتوز كيتوني (الشكل 6-9)', updated_at = now() where id = (select id from public.questions where objective_id = (select id from public.objectives where code = 'K22-C6-L2-O05') and type = 'mcq' and number = 4);
update public.question_answers set explanation = 'في (أ) مجموعة الكربونيل في طرف السلسلة مرتبطة بذرة H (ألدهيد)، وفي (ج) مجموعة الكربونيل على ذرة الكربون الثانية مرتبطة بذرتي كربون (كيتون)؛ فموقع مجموعة الكربونيل هو ما يجعل السكر الأحادي ألدهيدًا أو كيتونًا. وكلاهما C₆H₁₂O₆، فهما متشكلان بنائيان (الجلوكوز والفركتوز).' where question_id = (select id from public.questions where objective_id = (select id from public.objectives where code = 'K22-C6-L2-O05') and type = 'mcq' and number = 4);
update public.questions set images = '[{"src":"qimg/chem22/c6-l2-open-three.svg","alt":"ثلاثة تراكيب مفتوحة السلسلة لسكريات أحادية. (أ): سلسلة رأسية من ست ذرات كربون. في الأعلى ذرة H مرتبطة بذرة الكربون الأولى، وهذه مرتبطة برابطة ثنائية مع ذرة O يمينًا (H–C=O)؛ ثم ذرة كربون عليها H يسارًا وOH يمينًا؛ ثم ذرة كربون عليها HO يسارًا وH يمينًا؛ ثم ثلاث ذرات كربون على كلٍّ منها H يسارًا وOH يمينًا؛ وفي الأسفل ذرة H مرتبطة بآخر ذرة كربون. (ب): سلسلة رأسية مماثلة من ست ذرات كربون أعلاها H–C=O (ذرة H فوق ذرة الكربون الأولى)، ثم ذرة كربون عليها H يسارًا وOH يمينًا، ثم ذرتا كربون على كلٍّ منهما HO يسارًا وH يمينًا، ثم ذرتا كربون على كلٍّ منهما H يسارًا وOH يمينًا، وفي الأسفل ذرة H. (ج): سلسلة رأسية من ست ذرات كربون: في الأعلى ذرة H مرتبطة بذرة كربون عليها H يسارًا وOH يمينًا، تليها ذرة كربون مرتبطة برابطة ثنائية مع ذرة O يمينًا (C=O) دون ذرة H، ثم ذرة كربون عليها HO يسارًا وH يمينًا، ثم ثلاث ذرات كربون على كلٍّ منها H يسارًا وOH يمينًا، وفي الأسفل ذرة H."}]'::jsonb, source_ref = 'الكتاب ص 216–217 — الشكل 6-9: الجلاكتوز والجلوكوز', updated_at = now() where id = (select id from public.questions where objective_id = (select id from public.objectives where code = 'K22-C6-L2-O05') and type = 'mcq' and number = 6);
update public.question_answers set explanation = 'عند مقارنة الصفوف: ذرات الكربون الأولى والثانية والثالثة والخامسة والسادسة متطابقة في (أ) و(ب)، أما ذرة الكربون الرابعة فتحمل OH يمينًا في (أ) ويسارًا في (ب)؛ فالفرق في الاتجاه الفراغي حول ذرة كربون واحدة.' where question_id = (select id from public.questions where objective_id = (select id from public.objectives where code = 'K22-C6-L2-O05') and type = 'mcq' and number = 6);
